private void enlarge(final int size) {
    // Check if the size is negative
    if (size < 0) {
        throw new IllegalArgumentException("Size cannot be negative");
    }

    // Calculate the new size of the byte array
    int newSize = this.size + size;

    // Create a new byte array with the new size
    byte[] newBytes = new byte[newSize];

    // Copy the existing bytes to the new array
    System.arraycopy(this.bytes, 0, newBytes, 0, this.size);

    // Update the size of the byte array
    this.size = newSize;

    // Update the bytes array
    this.bytes = newBytes;
}
