public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Both target and resultMap cannot be null");
    }

    int numVertices = resultMap.size();
    if (numVertices <= 0) {
        throw new IllegalArgumentException("ResultMap must contain at least one vertex");
    }

    // Create two sets of vertices
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    // Populate the sets with vertices from resultMap
    for (V vertex : resultMap.values()) {
        set1.add(vertex);
    }

    // Create the bipartite graph
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}
