private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list cannot be null or empty");
    }

    List<Integer> lowerBounds = new ArrayList<>();
    int currentLowerBound = Integer.MAX_VALUE;

    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        int lowerBound = key.compareTo(currentLowerBound);
        if (lowerBound < 0) {
            currentLowerBound = lowerBound;
        }
        lowerBounds.add(currentLowerBound);
    }

    return lowerBounds;
}
